pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testRegression_property() public {
        address newOwner = address(1);
        vm.deal(newOwner, 1 ether);

        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        vm.prank(newOwner);
        c.acceptOwnership();

        assertTrue(c.pendingOwner() == address(0), "pendingOwner should be zero after acceptOwnership");
    }
}
